public class LightControl {
    public static void main(String[] args) {
        // 1 represents a lit bulb, 0 represents off
        int[] lightBulbs = {1, 1, 1, 1, 1, 1}; // Start with 6

        // Turn off every second bulb (odd indices)
        for (int i = 0; i < lightBulbs.length; i++) {
            if (i % 2 != 0) {
